// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 unused) internal {
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        uint256 balAfter = address(c).balance;
        assertTrue((reverted && balAfter == balBefore) || (!reverted && balAfter == 0));
    }

    function testFuzz_run(uint256 unused) public {
        _run(unused);
    }

    receive() external payable {}
}
